
-- 사고사례 테이블 생성
CREATE TABLE public.accident_cases (
  id uuid NOT NULL DEFAULT gen_random_uuid() PRIMARY KEY,
  accident_type text NOT NULL DEFAULT '',
  process_category text NOT NULL DEFAULT '',
  equipment text DEFAULT '',
  cause text NOT NULL DEFAULT '',
  result text NOT NULL DEFAULT '',
  fatality boolean DEFAULT false,
  injury_count integer DEFAULT 0,
  occurrence_date date DEFAULT NULL,
  location_type text DEFAULT '',
  description text DEFAULT '',
  prevention_measures text[] DEFAULT ARRAY[]::text[],
  related_law text DEFAULT '',
  risk_factors text[] DEFAULT ARRAY[]::text[],
  keywords text[] DEFAULT ARRAY[]::text[],
  source text DEFAULT '',
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now()
);

ALTER TABLE public.accident_cases ENABLE ROW LEVEL SECURITY;

CREATE POLICY "Anyone can view accident cases" ON public.accident_cases FOR SELECT TO authenticated USING (true);
CREATE POLICY "Admins can insert accident cases" ON public.accident_cases FOR INSERT TO authenticated WITH CHECK (is_admin(auth.uid()));
CREATE POLICY "Admins can update accident cases" ON public.accident_cases FOR UPDATE TO authenticated USING (is_admin(auth.uid()));
CREATE POLICY "Admins can delete accident cases" ON public.accident_cases FOR DELETE TO authenticated USING (is_admin(auth.uid()));

CREATE INDEX idx_accident_cases_process ON public.accident_cases(process_category);
CREATE INDEX idx_accident_cases_equipment ON public.accident_cases USING GIN(keywords);

